/**
 * dsh-diagrams — the vendored Mermaid build.
 *
 * Mermaid is the one engine this plugin needs on BOTH sides of the app: the
 * browser renders the diagram, and the host parses the same source headlessly
 * so the model gets a real error instead of a blank picture. The harness
 * profile installs this bundle as a live LINK, so a package dependency is not
 * installed and a plugin cannot `import 'mermaid'` - the engine is therefore
 * vendored, exactly like the editor's CodeMirror and the terminal's xterm.
 *
 * The artifact is mermaid's own SINGLE-FILE browser build
 * (`dist/mermaid.min.js`, ~3.5 MB). That choice is load-bearing:
 *
 *   - It is self-contained (zero dynamic imports, zero chunk requests), so the
 *     browser needs exactly ONE route and one request. The harness's
 *     Connection fetch registry registers EXACT routes only - there is no
 *     wildcard - so the chunked `dist/chunks/mermaid.esm.min/**` tree (104
 *     files) could only be served by registering 104 routes.
 *   - It loads as a classic script and ends with
 *     `globalThis["mermaid"] = ...`, so the browser gets `window.mermaid`
 *     directly.
 *   - The same bytes run headlessly in Node via `vm.runInThisContext` behind a
 *     small DOM stub (see `lib/mermaid-check.mjs`), which is what validates a
 *     diagram before it is stored. One vendored file, both halves.
 *
 * This script generates `lib/vendor/mermaid.min.js` from the pinned version in
 * `vendor/package.json` and records what it produced in `lib/vendor/VERSION.json`
 * (bytes + sha256), which the tracked route check re-computes to catch a
 * hand-edited or half-copied file.
 *
 * Usage:
 *   node build.mjs            rebuild the vendored engine from the pinned version
 *   node build.mjs --check    report drift against lib/vendor/VERSION.json
 */
import { createHash } from 'node:crypto'
import { spawnSync } from 'node:child_process'
import { copyFileSync, existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const pkgRoot = path.dirname(here)
const outDir = path.join(pkgRoot, 'lib', 'vendor')
const outFile = path.join(outDir, 'mermaid.min.js')
const versionFile = path.join(outDir, 'VERSION.json')
const check = process.argv.includes('--check')

const pin = JSON.parse(readFileSync(path.join(here, 'package.json'), 'utf8'))
const version = pin.dependencies.mermaid
if (typeof version !== 'string' || version.length === 0) {
  console.error('[dsh-diagrams/vendor] vendor/package.json pins no mermaid version')
  process.exit(1)
}

/** The installed engine's own version, or undefined when it is not installed. */
function installedVersion() {
  const manifest = path.join(here, 'node_modules', 'mermaid', 'package.json')
  if (!existsSync(manifest)) return undefined
  try {
    return JSON.parse(readFileSync(manifest, 'utf8')).version
  } catch (err) {
    return undefined
  }
}

/** The record this build writes and `--check` verifies. */
function manifest() {
  const bytes = readFileSync(outFile)
  return {
    package: 'mermaid',
    version,
    file: 'lib/vendor/mermaid.min.js',
    route: '/api/dsh-diagrams/vendor/mermaid.js',
    global: 'mermaid',
    bytes: bytes.byteLength,
    sha256: createHash('sha256').update(bytes).digest('hex'),
    note: 'GENERATED by vendor/build.mjs - never hand-edit lib/vendor/mermaid.min.js.',
  }
}

if (check) {
  if (!existsSync(outFile) || !existsSync(versionFile)) {
    console.error('[dsh-diagrams/vendor] no vendored engine - run: node packages/dsh-diagrams/vendor/build.mjs')
    process.exit(1)
  }
  const recorded = JSON.parse(readFileSync(versionFile, 'utf8'))
  const actual = manifest()
  if (recorded.sha256 !== actual.sha256 || recorded.bytes !== actual.bytes || recorded.version !== actual.version) {
    console.error('[dsh-diagrams/vendor] DRIFT: recorded ' + JSON.stringify(recorded))
    console.error('[dsh-diagrams/vendor] actual   ' + JSON.stringify(actual))
    console.error('[dsh-diagrams/vendor] rebuild with: node packages/dsh-diagrams/vendor/build.mjs')
    process.exit(1)
  }
  console.log('[dsh-diagrams/vendor] up to date: mermaid@' + actual.version + ', ' + actual.bytes + ' bytes')
  process.exit(0)
}

const present = installedVersion()
if (present !== version) {
  console.log('[dsh-diagrams/vendor] installing mermaid@' + version + ' (found ' + (present ?? 'nothing') + ') ...')
  const npm = process.platform === 'win32' ? 'npm.cmd' : 'npm'
  // A `.cmd` cannot be spawned without a shell on Windows (node refuses with
  // EINVAL), so the Windows half runs it through the command interpreter; the
  // stdio stays inherited so npm's own output is what the maintainer reads.
  const install = spawnSync(npm, ['install', '--no-audit', '--no-fund'], {
    cwd: here,
    stdio: 'inherit',
    shell: process.platform === 'win32',
  })
  if (install.error) console.error('[dsh-diagrams/vendor] npm could not start: ' + install.error.message)
  if (install.status !== 0) {
    console.error('[dsh-diagrams/vendor] npm install failed with status ' + install.status)
    process.exit(1)
  }
}

const source = path.join(here, 'node_modules', 'mermaid', 'dist', 'mermaid.min.js')
if (installedVersion() !== version || !existsSync(source)) {
  console.error('[dsh-diagrams/vendor] mermaid@' + version + ' is not installed under vendor/node_modules, or dist/mermaid.min.js is missing')
  process.exit(1)
}

mkdirSync(outDir, { recursive: true })
copyFileSync(source, outFile)
const record = manifest()
writeFileSync(versionFile, JSON.stringify(record, null, 2) + '\n', 'utf8')
console.log('[dsh-diagrams/vendor] wrote ' + record.file + ' (mermaid@' + record.version + ', ' + record.bytes + ' bytes)')
console.log('[dsh-diagrams/vendor] sha256 ' + record.sha256)
console.log('[dsh-diagrams/vendor] on disk now: ' + Math.round(statSync(outFile).size / 1024) + ' KiB')
